export default [{"id":224,"question":"ما حكم المسح على الخُفِّ المُمزق قليلًا؟","title":"ما حكم المسح على الخف الممزق؟","answer":"الجواب: الخُفَّان إذا كانا ساترين ولُبِسَا على طهارةٍ شُرع المسح عليهما في المدَّة المحددة، وهي يومٌ وليلةٌ للمُقيم بعد المسح، وثلاثة أيام بلياليها للمُسافر. أما إذا كانت فيهما خروقٌ فهذا فيه تفصيلٌ: إن كانت خروقًا تُعدّ يسيرةً عُرْفًا فالصواب جواز ذلك، هذا هو الصحيح من أقوال العلماء، جواز ذلك. أمَّا إذا كانت خروقًا تُعدُّ واسعةً عُرفًا فهذه لا يُمسح عليها، الشيء الخفيف القليل الذي مثل خط المخرز، مثل طرف الإصبع اليسير لا يضرُّ إن شاء الله، هذا على الصَّحيح، ولكن الخروج من الخلاف أولى؛ فكونه يخيطها أو يُبدلها أوْلى وأحسن، حتى لا يتوسَّع في هذا، وحتى يخرج من الخلاف.","link":"https://binbaz.org.sa/fatwas/4064/ما-حكم-المسح-على-الخف-الممزق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0231.mp3","categories":["المسح على الخفين"]},{"id":226,"question":"مسحت على الخُفين وأديت الصلاة، وبعد مدةٍ تذكرتُ أنَّ مدة المسح على الخفين قد انتهت، فهل عليَّ إعادة الصلاة؟","title":"حكم المسح على الخفين بعد انتهاء المدة ناسيًا","answer":"الجواب: نعم، الصلاة بعد المدة تُعيدها، كالصلاة التي تفعلها وأنت مُحْدِثٌ ناسٍ؛ تُعيدها.","link":"https://binbaz.org.sa/fatwas/4072/حكم-المسح-على-الخفين-بعد-انتهاء-المدة-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0233.mp3","categories":["المسح على الخفين"]},{"id":441,"question":"ما حكم المسح على الشَّراب (الجورب) المُخَرَّق؟","title":"ما حكم المسح على الشَّراب المُخَرَّق؟","answer":"الجواب: إن كانت الخروقُ يسيرةً يُعفى عنها إن شاء الله على الصحيح، ذهب جمعٌ من أهل العلم إلى أنَّ الخروق اليسيرة عُرفًا يُعفى عنها، أما إن كانت واسعةً فالواجب إبداله أو ترقيعُه.","link":"https://binbaz.org.sa/fatwas/4867/ما-حكم-المسح-على-الشراب-المخرق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0499.mp3","categories":["المسح على الخفين"]},{"id":1027,"question":"أفتى الشيخ محمد بن عثيمين بأنَّ مَن مسح على خفٍّ ثم خلعه فهو باقٍ على طهارته، حتى ولو كان المسحُ على الخفِّ بعد حدثٍ، فما قولكم؟","title":"ما حكم من مسح على خف ثم خلعه بعد حدث؟","answer":"الجواب: المسح على الخفَّين سنة ورخصة من الله جلَّ وعلا؛ رحمةً لعباده، وتيسيرًا عليهم، يمسح المقيم يومًا وليلةً، والمسافر ثلاثة أيام بلياليها، إذا لبس الخفَّين على طهارةٍ، أو الجوربين على طهارةٍ.\nوذكر أهلُ العلم أنه متى خلع الخفَّ بعد الحدث بطل وضوؤه، هذا هو الذي عليه أهلُ العلم، وهو جمهورهم.\nوقد قال بعضُ أهل العلم -وهو قولٌ شاذٌّ- أنه لا يبطل الوضوء بخلع الخفِّ، ولكنه قولٌ مرجوحٌ.\nوإن كان الابنُ الشيخ محمد بن عثيمين قال هذا الكلام فهو غلطٌ، تبع فيه بعضَ أهل العلم، وهو قولٌ مرجوحٌ، والصواب أنه متى خلع الخفَّين بطلت الطهارةُ، وكان عليه أن يتوضأ من جديدٍ إذا أراد أن يُصلي، أو يمسَّ المصحف، أو يطوف، ونحو ذلك، هذا هو المعتمد، وهذا هو الصواب الذي عليه جمهورُ أهل العلم.","link":"https://binbaz.org.sa/fatwas/21070/ما-حكم-من-مسح-على-خف-ثم-خلعه-بعد-حدث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0866ما حكم من مسح على حفٍ ثم خلعه بعد حدث؟ ابن باز فتاوى المحاضرات.mp3","categories":["المسح على الخفين"]},{"id":1335,"question":"هل للمسافر أن يمسح أكثر من ثلاثة أيام؟","title":"هل للمسافر أن يمسح أكثر من ثلاثة أيام؟","answer":"الجواب:\nالصواب ليس له إلا ثلاثة أيام.","link":"https://binbaz.org.sa/fatwas/21426/هل-للمسافر-ان-يمسح-اكثر-من-ثلاثة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في المسح على الخفين.mp3","categories":["المسح على الخفين"]},{"id":1538,"question":"الجوارب هل يُشترط أن تكون متينةً؟","title":"هل تشترط متانة الجورب للمسح عليه؟","answer":"الجواب:\nلا بدّ أن تستر قدمه، فإذا كانت شفافةً فلا يمسح عليها.","link":"https://binbaz.org.sa/fatwas/21638/هل-تشترط-متانة-الجورب-للمسح-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يشترط في الجوارب أن تكون متينة ليمسح عليها.mp3","categories":["المسح على الخفين"]},{"id":1549,"question":"إذا ابتدأ المقيمُ المسحَ ومضى على مسحه فترة بسيطة ثم سافر؟","title":"حكم مَن مسح وهو مقيم ثم سافر؟","answer":"الجواب:\nيُتم مسح مقيم: يوم وليلة.  وإن سافر قبل أن يمسح مسح ثلاثة أيام. والعكس: إذا وصل بعد تمام اليوم والليلة أو بعدها؛ لم يمسح.\nس: لا، أقصد إذا مسح مسح مقيمٍ ثم سافر، يبتدئ الآن من الفترة الأولى، أو يبتدئ مسحًا جديدًا على طول ثلاثة أيام؟\nج: ليس له إلا يوم وليلة، فما دام قد بدأ المسح وهو مقيم فيوم وليلة.","link":"https://binbaz.org.sa/fatwas/21650/حكم-من-مسح-وهو-مقيم-ثم-سافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسح وهو مقيم ثم سافر فما الحكم.mp3","categories":["المسح على الخفين"]},{"id":2994,"question":"مَنْ مَسَح مقيمًا ثم سافر هل يمسح مقيمًا أم مسافرًا؟","title":"حكم مَنْ مسح مُقيمًا ثم سافر","answer":"الجواب: يُكْمِل مُقيمًا، إن كان بدأ مقيمًا يكمل مقيمًا، وإن كان ما بدأ إلا في السفر يكمل في السفر.\nس: يعني يُغَلّب جانب الحَضَر؟\nالشيخ: نعم إذا كان قد بدأ.","link":"https://binbaz.org.sa/fatwas/23151/حكم-من-مسح-مقيما-ثم-سافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من مسح مقيما ثم سافر.mp3","categories":["المسح على الخفين"]},{"id":3417,"question":"السؤل:المسح على النعال صحيح؟","title":"هل يجوز المسح على النعال؟","answer":"الجواب: لا، النعال ما يُمسح عليها، يُمسح على الخفين، يُمسح على الجوربين.","link":"https://binbaz.org.sa/fatwas/23589/هل-يجوز-المسح-على-النعال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المسح على النعال.mp3","categories":["المسح على الخفين"]},{"id":4456,"question":"هل تُشترط النّية؟","title":"هل تُشترط النّية عند لبس الخفين؟","answer":"الجواب: لا، ما هو بشرط النية، لو لبسهما على طهارةٍ ولم ينوِ أنه يمسح أو يخلع، ثم بقي عليه، يمسح ولا بأس.","link":"https://binbaz.org.sa/fatwas/24734/هل-تشترط-النية-عند-لبس-الخفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تُشترط النّية عند لبس الخفين.mp3","categories":["المسح على الخفين"]},{"id":4457,"question":"إذا انتهت مدةُ المسح هل ينتقض الوضوء؟","title":"هل ينتقض الوضوء إذا انتهت مدةُ المسح؟","answer":"الجواب: نعم، المعروف عند أهل العلم أنه ينتقض،... بعد أن تنتهى المدة يخلع ويتوضأ، انتهت الطهارة. س: الدليل يا شيخ؟ ج: التوقيت، توقيت النبي ﷺ، وقَّت النبيُّ ﷺ.","link":"https://binbaz.org.sa/fatwas/24735/هل-ينتقض-الوضوء-اذا-انتهت-مدة-المسح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ينتقض الوضوء إذا انتهت مدةُ المسح على الخفين.mp3","categories":["المسح على الخفين"]},{"id":4458,"question":"إذا كان في الجوربين خرقٌ في باطن القدم؟","title":"ما حكم الخروق اليسيرة في الجورب؟","answer":"الجواب: الصحيح أنه يُعْفَى عن الشيء اليسير، وإذا احتاط وترك، خاطه أو رقعه؛ يكون أحسن، أو أبدله، لكن الصحيح أن الشيء اليسير عُرْفًا يُعْفَى عنه، الخرق اليسير.","link":"https://binbaz.org.sa/fatwas/24736/ما-حكم-الخروق-اليسيرة-في-الجورب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يمسح على الجوربين إذا كان فيها خرقٌ في باطن القدم.mp3","categories":["المسح على الخفين"]},{"id":4459,"question":"والجوارب الرَّقيقة؟","title":"هل يُمسح على الجوارب الشفافة؟","answer":"الجواب: لا بدّ أن يكون ساترًا، الخفّ والعمامة والجورب لا بدّ أن يكون ساترًا لمحل الفرض، فإن كان شفَّافًا لا يمسح عليه.","link":"https://binbaz.org.sa/fatwas/24737/هل-يمسح-على-الجوارب-الشفافة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُمسح على الجوارب الرَّقيقة.mp3","categories":["المسح على الخفين"]},{"id":4460,"question":"الدليل على أنَّ الواجب أن يكون ساترًا وهو مُقيم؟","title":"ما دليل وجوب ستر الخفّين للقدم للمسح عليهما؟","answer":"الجواب: الظاهر عموم الأدلة في الخفّين والجوربين؛ أنهما فعلا وقاية للقدم، وإرفاقًا للعبد وتسهيلًا عليه لحاجاته، فالرقيق لا يحصل به المقصود من هذا.","link":"https://binbaz.org.sa/fatwas/24738/ما-دليل-وجوب-ستر-الخفين-للقدم-للمسح-عليهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدليل على أنَّ الواجب في الخفّين والجوربين أن يكون ساترًا.mp3","categories":["المسح على الخفين"]},{"id":4461,"question":"التوقيت يكون من بداية المسح أو من بداية (الاغتسال)؟","title":"متى يبدأ التوقيت في المسح على الخفين؟","answer":"الجواب: لا، بعد الحدث، المسح بعد الحدث، يحسب من مسحه بعد الحدث، فإذا لبسها مثلًا صلاة العصر، ولم يُحدث إلا بعد العشاء، يكون مسحه بعد العشاء، العصر والمغرب والعشاء لا تُحسب، المدة يوم وليلة بعد المسح، وثلاثة أيام بلياليها بعد المسح، بعد حدثه يعني.","link":"https://binbaz.org.sa/fatwas/24739/متى-يبدا-التوقيت-في-المسح-على-الخفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يبدأ التوقيت في المسح على الخفين.mp3","categories":["المسح على الخفين"]},{"id":4462,"question":"لو توضأ وغسل الرِّجْل اليُمنى ولبس عليها الخفّ، ثم غسل اليُسرى ولبس الخفّ عليها؟","title":"حكم لبس خُفِّ اليمنى قبل غسل اليسرى","answer":"الجواب: فيه خلافٌ بين أهل العلم: منهم مَن يُجيز هذا؛ لبس اليمنى ثم غسل اليسرى ولبس الخفّ عليها، جمعٌ من أهل العلم يقولون أنه يمسح؛ لأنه لبس هذه على طهارةٍ، وهذه على طهارةٍ، ولكن الأولى لم تكن طهارة كاملة، لكنها في معنى الكاملة.  ولكن الأوْلى بالمؤمن في مثل هذا أن يخرج من الخلاف، فإذا غسل اليسرى وانتهى منها وقد لبس اليمنى، يخلعها، ثم يُعيد لبسها؛ حتى لا يبقى الخلافُ، ولا يقع إشكال؛ حتى يكون لبسهما على طهارةٍ، حتى يسلم من الخلاف.","link":"https://binbaz.org.sa/fatwas/24740/حكم-لبس-خف-اليمنى-قبل-غسل-اليسرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يمسح على الخف إذا غسل الرِّجْل اليُمنى ولبس عليها الخفّ، ثم غسل اليُسرى ولبس الخفّ عليها.mp3","categories":["المسح على الخفين"]},{"id":4463,"question":"كيف المسح على النَّعلين إذا انعدم الماء؟","title":"حكم النَّعلين والجوربين بعد المسح عليهما","answer":"الجواب: إذا كان على الجوربين مسح عليهما جميعًا، مثل: الكندرة على الجورب، ربما تستر، فإذا مسح عليهما جميعًا لا بأس، لكن متى خلع نعليه خلع الأسفل؛ صار الحكم لهما جميعًا.  وأما إذا مسح الجورب من تحت النعل - خلع النعل ومسح على الجورب، أو خلع الكندرة ومسح الجورب - صار الحكمُ للجورب، والنعل يخلعها متى شاء، والكندرة يخلعها متى شاء؛ لأنَّ الحكم صار للممسوح عليه وهو الجورب.\nس: ألا تكون الكندرة منفصلة عن الجورب؟\nج: ولو مُنفصلة، لو مسح عليهما جميعًا يبقى لهما جميعًا، فإذا خلع الكندرة أو خلع النعل يخلع الجورب، أما إذا خلع ومسح على الجورب دون الكندرة دون النعل فالحكم يختص بالجورب، كما فعله الصحابة رضي الله عنهم وأرضاهم.","link":"https://binbaz.org.sa/fatwas/24741/حكم-النعلين-والجوربين-بعد-المسح-عليهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المسح على النَّعلين إذا انعدم الماء.mp3","categories":["المسح على الخفين"]},{"id":4464,"question":"إذا كان المسحُ وهو مُقيم ثم سافر؟","title":"حكم من مسح على الخف مُقيمًا ثم سافر","answer":"الجواب: إذا سافر قبل أن يمسح يمسح ثلاثة أيام، أما إذا كان بعد أن شرع في المسح، بعد أن مسح، المعروف عند أهل العلم أنه يكون مسح مقيم؛ تغليبًا لجانب الحظر.","link":"https://binbaz.org.sa/fatwas/24742/حكم-من-مسح-على-الخف-مقيما-ثم-سافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من مسح على الخف مُقيمًا ثم سافر.mp3","categories":["المسح على الخفين"]},{"id":4465,"question":"إذا انعدم الماء، ثم تيمم ولبس الجوربين، ثم وجد الماء، هل يمسح عليهما؟","title":"هل يمسح على الجوربين من لبسهما بعد تيمم؟","answer":"الجواب: يخلعهما؛ لأنه مسح عليهما من غير طهارة الماء، طهارة التراب طهارة ناقصة بالنسبة إلى الماء، فلا يمسح عليهما إلا بعد طهارةٍ كاملةٍ التي فعلها النبيُّ ﷺ.","link":"https://binbaz.org.sa/fatwas/24743/هل-يمسح-على-الجوربين-من-لبسهما-بعد-تيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يمسح على الجوربين من تيمم ولبس الجوربين.mp3","categories":["المسح على الخفين"]},{"id":4482,"question":"المسح على الجبيرة مقيس على أصحاب الخُفَّين؟","title":"ما دليل المسح على الجبيرة؟","answer":"الجواب: هذا هو الأصل، يعني: من باب أولى، مع اعتضاد الحديث بعمل بعض الصحابة: كابن عمر، والحديث ضعيف، إذا عضده أصلٌ أو عضده فعلُ الصحابة كان من باب الحسن لغيره.\nس: يعني: يكون قياسًا أوليًّا؟\nج: نعم.\nس: إذا عضَّده أصلٌ أو عضَّده فعلُ ابن عمر؟\nج: أولًا: الذي يعتضد بفعل ابن عمر يكون من باب الحسن لغيره، وثانيًا: من جهة أن أحاديث المسح على الخفَّين تدل على هذا من باب أولى.","link":"https://binbaz.org.sa/fatwas/24762/ما-دليل-المسح-على-الجبيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقاس المسح على الجبيرة على الخُفَّين.mp3","categories":["المسح على الخفين"]},{"id":4576,"question":"مَن لبس الشراب بعد العصر وأحدث بعد العشاء وأول مسح في الفجر؟","title":"متى يبدأ وقت المسح على الخفين؟","answer":"الجواب: يبدأ المسح من الفجر.\nس: الحساب من الفجر؟\nج: نعم، مبدأه من الفجر .","link":"https://binbaz.org.sa/fatwas/24860/متى-يبدا-وقت-المسح-على-الخفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يبدأ وقت المسح عند من لبس الخف بعد العصر، وأحدث بعد العشاء.mp3","categories":["المسح على الخفين"]},{"id":5069,"question":"الشُّرَّاب المُجْزِئ؟","title":"ما مواصفات الجورب الذي يجوز المسح عليه؟","answer":"الجواب: اللي يَسْتُر، اللي يَسْتُر ولو من صوف أو قطن، ما هو بلزوم الجلد، اللي يَسْتُر البشرة يكفي.\nس: إلى الكعبين ولكن مخروق؟\nج: يكون سليمًا، والخروق اليسيرة يُعفى عنها.\nس: الشُّرَّاب الشفاف يجوز المسح عليه؟\nج: لا بدّ يغطي يَسْتُر البشرة، فإذا كان ما يَسْتُر ذكر أهل العلم أنه لا يُجزئ.","link":"https://binbaz.org.sa/fatwas/29365/ما-مواصفات-الجورب-الذي-يجوز-المسح-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما مواصفات الجورب الذي يجوز المسح عليه؟.mp3","categories":["المسح على الخفين"]},{"id":5568,"question":"ما يُشترط أنه ينوي المسح على الخفَّين قبل أن يلبسهما؟","title":"هل تشترط نية المسح على الخفين قبل لبسهما؟","answer":"الجواب: لا، ما يشترط، إذا لبسهما على طهارةٍ كفى، والحمد لله، ولو ما نوى قبل الوضوء.[1]","link":"https://binbaz.org.sa/fatwas/31520/هل-تشترط-نية-المسح-على-الخفين-قبل-لبسهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 008.mp3","categories":["المسح على الخفين"]},{"id":5569,"question":"وإذا مسحهما في وقتٍ واحدٍ؟","title":"هل يستحب التيامن في المسح على الخفين؟","answer":"الجواب: يجوز إذا عمم، ما يضرّ، المهم التَّعميم، لكن السنة هكذا وهكذا، أسهل عليه، كان النبي ﷺ يمسح اليمنى باليمنى، واليسرى باليسرى. س: في الزمن -زمن المسح- ما يُقدم اليُمنى؟ ج: نعم يُقدم اليمنى على قاعدة: إذا توضأتم فابدؤوا بميامنكم. س: وإذا مسحهما في وقتٍ واحدٍ؟ ج: الجمهور يرى أنه يصحّ، يرى التيامن أفضلية. س: في المسح أو في الغسل؟ ج: التيامن أفضلية. س: سواء كان في الغسل أو في المسح؟ ج: نعم أفضلية، لكن الأحوط للمؤمن أن يحتاط، الأحوط للمؤمن أن يعتني بالأفضلية بالأيمن؛ لقوله ﷺ: إذا توضَّأتم فابدؤوا بميامنكم، وكان يتوضأ ويبدأ بالميامن عليه الصلاة والسلام.[1]","link":"https://binbaz.org.sa/fatwas/31521/هل-يستحب-التيامن-في-المسح-على-الخفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 009.mp3","categories":["المسح على الخفين"]},{"id":5793,"question":"لبست الشراب بعد غسل الرجل اليسرى، ثم لبسته، ثم غسلت اليمنى ولبست الشراب؟","title":"لبس الجورب للرِجل اليمني قبل غسل الرِجل اليسرى","answer":"الجواب:  لعلها العكس، غسل اليمنى، ثم لبس الشراب، ثم غسل اليسرى، ولبس الشراب هذه عادة الناس. تكملة السؤال: فهل هذا لا يؤثر على كمال طهارتي، أم لا؟  الجواب: ذكر بعض أهل العلم أنه إذا غسل اليمنى، ثم لبس الخف، أو الشراب فيها، ثم غسل اليسرى، ثم إنه لبس اليمنى قبل أن تتم الطهارة، والنبي ﷺ قال: أدخلتهما طهارتين فالعلماء قالوا: لا بدّ من شرط المسح أن يدخلهما طهارتين، فلهذا قال بعضهم: لا يمسح على هذه الطهارة إلا إذا أخرج اليمنى، ثم أعادها، فإذا أخرج اليمنى بعد غسل اليسرى، ثم لبسها بعد ذلك حتى يكون لبسهما على طهارة كاملة، وهذا من باب الاحتياط الحسن. إذا لبس اليمنى الشراب يعني، أو الخف في اليمنى، ثم غسل اليسرى، ثم لبس الخف فيها بعد ذلك؛ فالأحوط أن يخلع اليمنى، ثم يعيد لبسها حتى يكون لبسها بعد طهارة كاملة، ولو لم يفعل، فالصحيح أنه يجزئ، اختاره شيخ الإسلام ابن تيمية، وجماعة، وقالوا: إن الطهارة حين لبس اليمنى قد قاربت، وهو في حكم الطاهرين؛ لأن الطهارة اتصلت، وانتهت بسرعة بطهارة كاملة، فصح ذلك؛ لأنه ما بقي إلا غسل اليسرى. فالطهارة الآن قد قاربت، فإذا لبس اليمنى قبل غسل اليسرى؛ فالطهارة مقاربة، وقد انتهت على وجه شرعي في الحال، وكملها في الحال، فتصح، ولا حاجة إلى خلع اليمنى، ثم لبسها، ولكن إذا خلع، ثم لبس حتى يخرج من الخلاف، وحتى يكون لبس اليمنى على طهارة كاملة فحسن، وفيه بعد عن الشبهة، وعن الريب، وعن الخلاف.","link":"https://binbaz.org.sa/fatwas/1113/لبس-الجورب-للرجل-اليمني-قبل-غسل-الرجل-اليسرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_119.mp3","categories":["المسح على الخفين"]},{"id":5803,"question":"لبست الشراب بعد الوضوء، وكمال الطهارة، ثم بعد وقت، أو وقتين لبست شرابًا آخر؛ اتقاء للبرد وأنا محدث، فهل يجوز المسح على الشراب الآخر؟","title":"مسألة في المسح على الجوارب","answer":"الجواب:  هذا يذكر أنه لبس الشراب على طهارة، وبعدما مضى وقت، أو وقتان لبس عليه شرابًا آخر للدفء، وقد أحدث، وليس على طهارة. والجواب: لا يمسح على الشراب الثاني، ما يجوز؛ لأنه لبسها على غير طهارة، أما لو لبسها على طهارة، يعني توضأ ومسح على الخف الأول، ثم لبس الخف الثاني على طهارة؛ جاز المسح عليه؛ لأنه لبسه على طهارة. أما إذا كان لبسه بعدما أحدث، فإنه يكون لبسه على غير طهارة، فلا يمسح.","link":"https://binbaz.org.sa/fatwas/1124/مسالة-في-المسح-على-الجوارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_130.mp3","categories":["المسح على الخفين"]},{"id":6129,"question":"ما دام الإنسان على طهارة بالمسح؟","title":"حكم المسح على الخفين بعد خلعهما بعد المسح","answer":"الجواب: إذا مسح الخفين إذا أحدث بعدما لبس الخفين على طهارة، أحدث بعد لبسهما على طهارة ثم مسح عليهما، أو خلعهما قبل ذلك؛ فإنه لا يلبسهما إلا على طهارة، وطهارته قد فسدت، ولو مسح عليهما في الطهارة الجديدة؛ لأن الخف شرط في بقاء الطهارة، فإذا خلعه؛ انتقضت الطهارة، هذا الذي عليه عامة أهل العلم: أن خلع الخف بعد ما مسح عليه بعد الحدث؛ ينقض الطهارة، بل يبقى الخف عليه حتى يتم.. فإذا أراد خلعه قبل انتهاء المدة؛ فلا بأس، يخلعه، ولكن يعيد الطهارة، لا تبقى معه طهارته إذا كان قد أحدث. أما لو لبس الخفين على طهارة، ثم خلعهما قبل أن يحدث، فما فيه شيء، هو على طهارته، لكن إذا أحدث، ثم تطهر، ومسح عليهما، ثم خلعهما؛ تبطل الطهارة عند عامة أهل العلم، عند أكثر أهل العلم، وهو كالإجماع.","link":"https://binbaz.org.sa/fatwas/1538/حكم-المسح-على-الخفين-بعد-خلعهما-بعد-المسح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_468.mp3","categories":["المسح على الخفين"]},{"id":6305,"question":"سماحة شيخنا، نأمل توضيح بداية المسح على الخفين، ونهاية ذلك، هل هو من أول حدث، أم من أول بداية المسح؟","title":"وقت احتساب البداية والنهاية في المسح على الخفين","answer":"الجواب: إذا لبس الخفين الساترين على طهارة، مسح عليهما يوم وليلة للمقيم، وثلاثة أيام بلياليها للمسافر، والبدء عند جمع من أهل العلم يكون من الحدث بعد اللبس، إذا أحدث بعد لبسه إياها؛ بدأ، والأرجح أن المسح يكون بعد الحدث، إذا مسح بعد الحدث، هذا هو المبدأ، هذا هو أرجح الأقوال في هذا، فإذا لبسها مثلاً الفجر على طهارة، ربما أحدث الضحى، ثم مسح عليها الظهر، فالبدء من الظهر، لا يزال يصلي فيها، ويمسح إلى الظهر، إذا جاء الظهر القابل؛ خلعها، وتوضأ، ثم لبسها إلى الظهر.  وهكذا لو لبسها الظهر على طهارة، ثم أحدث بعد الظهر، ثم مسح عليها العصر، يكون المبدأ من العصر، فلا يزال يتوضأ، ويمسح عليها إلى العصر، إذا جاء العصر القادم؛ خلعها، ويتوضأ وضوء الصلاة، ثم يلبسها إن شاء. أما المسافر ثلاثة أيام بلياليها، اثنين وسبعين ساعة بعد المسح، بعد المسح عليها يبدأ اثنين وسبعين ساعة ثلاثة أيام بلياليها، وهو يمسح، هذا إن وجد الماء، إن ما وجد الماء يخليها عليه، ولو أيام كثيرة، مثل إذا كان ما له إلا التيمم ما يلزم خلعها للتيمم؛ لأنه ما في  مسح على الرجلين على الصحيح، وإنما هذا إذا وجد الماء في السفر؛ يخلع بعد ثلاثة أيام بلياليها، ويتوضأ، ويغسل رجليه، ثم يلبسها مرة أخرى إذا شاء، أما إذا كان في السفر الطويل، ولا عنده ماء يتيمم؛ فإنه لا بأس أن تبقى في رجليه، ولو أسابيع ما دام في السفر إذا ما وجد ماء.","link":"https://binbaz.org.sa/fatwas/1886/وقت-احتساب-البداية-والنهاية-في-المسح-على-الخفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_669.mp3","categories":["المسح على الخفين"]},{"id":6319,"question":"سماحة شيخنا، نأمل توضيح بداية المسح على الخفين، ونهاية ذلك، هل هو من أول حدث، أم من أول بداية المسح؟","title":"وقت احتساب البداية والنهاية في المسح على الخفين","answer":"الجواب: إذا لبس الخفين الساترين على طهارة، مسح عليهما يوم وليلة للمقيم، وثلاثة أيام بلياليها للمسافر، والبدء عند جمع من أهل العلم يكون من الحدث بعد اللبس، إذا أحدث بعد لبسه إياها؛ بدأ، والأرجح أن المسح يكون بعد الحدث، إذا مسح بعد الحدث، هذا هو المبدأ، هذا هو أرجح الأقوال في هذا، فإذا لبسها مثلاً الفجر على طهارة، ربما أحدث الضحى، ثم مسح عليها الظهر، فالبدء من الظهر، لا يزال يصلي فيها، ويمسح إلى الظهر، إذا جاء الظهر القابل؛ خلعها، وتوضأ، ثم لبسها إلى الظهر.  وهكذا لو لبسها الظهر على طهارة، ثم أحدث بعد الظهر، ثم مسح عليها العصر، يكون المبدأ من العصر، فلا يزال يتوضأ، ويمسح عليها إلى العصر، إذا جاء العصر القادم؛ خلعها، ويتوضأ وضوء الصلاة، ثم يلبسها إن شاء. أما المسافر ثلاثة أيام بلياليها، اثنين وسبعين ساعة بعد المسح، بعد المسح عليها يبدأ اثنين وسبعين ساعة ثلاثة أيام بلياليها، وهو يمسح، هذا إن وجد الماء، إن ما وجد الماء يخليها عليه، ولو أيام كثيرة، مثل إذا كان ما له إلا التيمم ما يلزم خلعها للتيمم؛ لأنه ما في  مسح على الرجلين على الصحيح، وإنما هذا إذا وجد الماء في السفر؛ يخلع بعد ثلاثة أيام بلياليها، ويتوضأ، ويغسل رجليه، ثم يلبسها مرة أخرى إذا شاء، أما إذا كان في السفر الطويل، ولا عنده ماء يتيمم؛ فإنه لا بأس أن تبقى في رجليه، ولو أسابيع ما دام في السفر إذا ما وجد ماء.","link":"https://binbaz.org.sa/fatwas/1886/وقت-احتساب-البداية-والنهاية-في-المسح-على-الخفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_669.mp3","categories":["المسح على الخفين"]},{"id":6340,"question":"مدة المسح للمقيم يوم وليلة، ما هو الحكم إذا انتهت المدة، وأنا مسافر مسافة 200 كيلو تقريبًا، فهل أتم وأصلي، أم أصبر حتى أصل إلى البلد التي سأقيم بها؟","title":"حكم من انتهت مدة مسحه على الخفين ولم يجد ماء","answer":"الجواب: إذا انتهت المدة؛ يكفي التيمم، إذا ما عندك ماء، إذا انتهت مدة المسح، وأنت ما عندك ماء، ما في حاجة إلى خلعها، تذهب إلى التراب، وتتيمم، والحمد لله إذا كنت في برية، وما عندك ماء.  أما إذا كان عندك ماء فاخلع اخلع إذا تمت المدة، وتوضأ، واغسل رجليك. وأما إذا كنت في السفر، ولا عندك ماء؛ فالصواب عند أهل العلم: أنه لا حاجة إلى خلعها؛ لأنها لا تمسح، المسح بالوجه، والكفين فقط، ولا حاجة إلى خلعها.","link":"https://binbaz.org.sa/fatwas/1937/حكم-من-انتهت-مدة-مسحه-على-الخفين-ولم-يجد-ماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_722.mp3","categories":["المسح على الخفين"]},{"id":6347,"question":"لو كان لبسها على نية أنه مقيم، لكن طرأ عليه سفر، وسافر؟","title":"حكم من لبس خفيه وهو مقيم ثم سافر","answer":"الجواب: إذا سافر قبل أن يمسح عليها لبسها على الطهارة، وسافر؛ يمسح ثلاثة أيام بلياليها، وإذا كان مسح يتمم على مسح  المقيم يوم وليلة، إذا بدأ المسح وهو مقيم؛ يتمم مسح المقيم.","link":"https://binbaz.org.sa/fatwas/1938/حكم-من-لبس-خفيه-وهو-مقيم-ثم-سافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_723.mp3","categories":["المسح على الخفين"]},{"id":6369,"question":"مدة المسح للمقيم يوم وليلة، ما هو الحكم إذا انتهت المدة، وأنا مسافر مسافة 200 كيلو تقريبًا، فهل أتم وأصلي، أم أصبر حتى أصل إلى البلد التي سأقيم بها؟","title":"حكم من انتهت مدة مسحه على الخفين ولم يجد ماء","answer":"الجواب: إذا انتهت المدة؛ يكفي التيمم، إذا ما عندك ماء، إذا انتهت مدة المسح، وأنت ما عندك ماء، ما في حاجة إلى خلعها، تذهب إلى التراب، وتتيمم، والحمد لله إذا كنت في برية، وما عندك ماء.  أما إذا كان عندك ماء فاخلع اخلع إذا تمت المدة، وتوضأ، واغسل رجليك. وأما إذا كنت في السفر، ولا عندك ماء؛ فالصواب عند أهل العلم: أنه لا حاجة إلى خلعها؛ لأنها لا تمسح، المسح بالوجه، والكفين فقط، ولا حاجة إلى خلعها.","link":"https://binbaz.org.sa/fatwas/1937/حكم-من-انتهت-مدة-مسحه-على-الخفين-ولم-يجد-ماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_722.mp3","categories":["المسح على الخفين"]},{"id":6534,"question":"رجل يمسح على جوربه، وبعد صلاة الظهر مباشرة وجد فيه ثقبًا، ولا يدري كم صلاة صلاها بهذا الثقب؟","title":"حكم المسح على الجورب إن كان مثقوباً","answer":"الجواب: إذا كان الثقب خفيفًا قليلًا ما يضر، صلاته صحيحة، وإن كان الثقب واسعًا كثيرًا يعيد الصلاة الأخيرة فقط، يتوضأ ويعيد الصلاة.","link":"https://binbaz.org.sa/fatwas/2375/حكم-المسح-على-الجورب-ان-كان-مثقوبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_909.mp3","categories":["المسح على الخفين"]},{"id":8001,"question":"من العامل يحيى محمد حسن موسى من جمهورية مصر العربية يقول: إنني عامل في السعودية وفقني الله بصلاة مع عمالي، ولكن الرجل الذي يؤم الناس في صلاة الجماعة وجدته في الوضوء يمسح رجله بالماء من فوق الشراب، فقلت له: لماذا لم تخلع الشراب لتعم الماء على رجلك؟ فقال لي: سألت المطوع قال: يجوز الماء بالمسح فوق الشراب، فهل تكون الصلاة صحيحة أم لا؟ والسؤال مهم لدينا وفقكم الله؟","title":"حكم المسح على الجوربين","answer":"الجواب: نعم، يجوز المسح على الشراب إذا كانت ساترة للرجل يجوز المسح عليها، إذا لبسها على طهارة فلا حرج في ذلك، والنبي ﷺ مسح على الجوربين والنعلين، ثبت عنه ذلك ﷺ، وثبت عن جماعة من الصحابة من أصحاب النبي ﷺ أنهم كانوا يمسحون على الجوارب، والجوارب هي الشراب من القطن أو من الصوف ونحو ذلك، أما الخف فهو من الجلد، والنبي مسح على خفيه ﷺ ومسح الجوربين أيضاً، فلا حرج في ذلك.\nومن قال: إنه لا يمسح إلا على الخف فقط من الجلد، فهو قول ضعيف مرجوح، والصواب أنه يمسح على الجلد وعلى الجورب الذي هو الشراب من القطن أو من الصوف إذا كان ساتراً للقدمين، وإذا كان لبسهما على طهارة، فإنه يمسح يوم وليلة للمقيم، وثلاثة أيام بلياليها للمسافر بعد الحدث هذا هو المشروع، وبذلك تعلم أن مسحه لا حرج فيه وأن صلاتكم صحيحة، وأن قول من قال: إن المسح يكون في الخف الذي هو من الجلد ليس بجيد. نعم.","link":"https://binbaz.org.sa/fatwas/5555/حكم-المسح-على-الجوربين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_074/07403.mp3","categories":["المسح على الخفين"]},{"id":8427,"question":"هل يجوز فسخ الشراب بعد أداء الفروض الخمسة للماسح عليها يوم وليلة؟ وعند اتساخها، هل يصح لي تغييرها قبل إكمال الفروض ومتابعة المسح عليها؟ والقصد من سؤالي: هو إراحة الأرجل عند النوم وذلك بعد أداء الفروض جميعها، ابتداءً من صلاة الفجر حتى العشاء، والفترة ما بين العشاء والفجر راحة، راجين إفادتي بذلك، والله يوفقكم؟","title":"حكم المسح على الجوربين بعد خلعهما قبل تمام المدة","answer":"الجواب: المشروع للمؤمن أن يمسح يوماً وليلة إذا كان مقيماً، وثلاثة أيام بلياليها إذا كان مسافراً، كما ثبت عن رسول الله عليه الصلاة والسلام من حديث علي ، أن النبي ﷺ قال: يمسح المقيم يوم وليلة والمسافر ثلاثة أيام بلياليها، وهكذا جاء في أحاديث أخرى عن النبي عليه الصلاة والسلام، والبدء يكون بعد الحدث، إذا مسح بعد الحدث هذا البدء، فإذا أحدث الضحى مثلاً ثم توضأ للظهر ولبسها ثم مسح للعصر فإنه يستمر إلى العصر الآتي، فإذا جاء العصر الآتي خلعها وغسل رجليه قبل العصر، ثم لبسهما بعد ذلك، ثم يمسح يوم وليلة بعد ذلك.\nأما إذا خلعهما للراحة، مثلاً لبسهما بعد الظهر على الطهارة، ثم مسح عليهما بعد العصر، ثم مسح بعد المغرب والعشاء، ثم خلعهما بعد العشاء للنوم، فإنه يغسل قدميه إذا قام للفجر، ولا يلبسهما إلا على طهارة، يغسل قدميه يتوضأ وضوء الصلاة ويغسل قدميه، ثم يلبسهما على طهارة، فيمسح عليهما بعد ذلك الضحى إذا صلى الضحى، أو يمسح عليهما الظهر أو العصر هكذا، يوم وليلة مرة أخرى وهكذا.\nوإذا خلعهما بعدما أحدث، فإنه يبطل حكم المسح، فليس له أن يعيدهما إلا على طهارة جديدة، يتوضأ ثم يلبسهما على طهارة جديدة، ولا يلبسهما على طهارة سبقت قبل الخلع، لا، متى خلعهما بطل حكم المسح، حتى يتوضأ وضوءاً جديداً ثم يلبسهما بعد الوضوء الجديد، ولهذا لما توضأ النبي ﷺ وعليه خفان، فأراد أن يمسح عليهما، وأراد المغيرة أن ينزعهما، فقال النبي ﷺ: دعهما فإني أدخلتهما طاهرتين، وجاء عنه ﷺ: إذا توضأ المؤمن ثم لبسهما يمسح، وهكذا جاء في حديث صفوان بن عسال  قال: أمرنا الرسول ﷺ إذا كنا سفراً أن لا ننزع خفافنا ثلاثة أيام ولياليهن إلا من جنابة، ولكن من غائط وبول ونوم، فالمؤمن يمسح ثلاثة أيام بلياليها في السفر، ويمسح في الإقامة يوم وليلة لكن في غير جنابة، أما الجنابة فلا، لابد من الخلع، حتى يغسل قدميه في الجنابة. نعم.","link":"https://binbaz.org.sa/fatwas/6311/حكم-المسح-على-الجوربين-بعد-خلعهما-قبل-تمام-المدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_119/11904.mp3","categories":["المسح على الخفين"]},{"id":8547,"question":"يقول: إذا مسحت على الخف فقط، وأنا قد لبسته ولبست تحته جورباً، فلما أردت الصلاة خلعت الخف الذي مسحت عليه وصليت في الجورب فما الحكم في ذلك؟","title":"بعض أحكام المسح على الخفين","answer":"الجواب: إذا كان قد أحدث فلا يمسح حينئذ؛ لأنه خلع الممسوح عليه فبطل الوضوء، أما إذا كان لم يحدث بل خلعه وإنما مسح على الخف مسح وضوء نافلة وضوء تطوع لم يحدث فيه وإنما هو وضوء تجديد لم يحدث فيه فإنه يمسح على الجورب الأخير الساتر إذا كان ساتراً؛ لأن طهارته التي لبس عليها لا تزال باقية، إذا كانت الطهارة باقية التي لبس عليها الجورب والخف ثم توضأ وضوءاً يعني: تجديداً على غير حدث بل لمجرد التجديد والنشاط، فإنه يمسح على الجورب الذي لبسه على طهارة، أما إذا كان قد أحدث، فإنه يخلع حينئذ ويجدد الطهارة ثم يلبس بعده إذا شاء.\nالمقدم: ثم يقول: ما الحكم لو خلعهما جميعاً؟\nالشيخ: إذا خلعهما جميعاً فإنه يبطل الوضوء إذا كان قد أحدث، أما إذا كان ما بعد أحدث هو على طهارته الأولى التي لبس عليها الجورب والخف فطهارته على حاله صحيحة، ما يخل بها خلع الجورب والخف؛ لأنه لم يحدث. نعم.\nالمقدم: ثم يقول: هل يصح أن يمسح لفرضين أو ثلاثة ثم يخلعهما عند النوم ويستأنف الطهارة من الغد؟\nالشيخ: لا بأس، ما هو لازم يبقى فيها يوم وليلة ما هو لازم، لو لبس الخفين ومسح عليهما فرضاً أو فرضين ثم خلعهما لا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/6617/بعض-احكام-المسح-على-الخفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20508.mp3","categories":["المسح على الخفين"]},{"id":9269,"question":"هل هناك من إرشاد حول المسح على الجوربين؟","title":"أحكام المسح على الجوارب","answer":"الجواب: نعم، يمسح عليهما يوماً وليلة في حق المقيم وثلاثة أيام بلياليها في حق المسافر إذا كانا ساترين لمحل الفرض الكعبين وما دونهما من القدم، ساترين يعني: صفيقين فإنهما يمسح عليهما بشرط أن يكونا طاهرين مباحين لا مغصوبين ولا نجسين.\nفالمقصود أنه إذا كان الجوربان أو الخفان طاهرين مباحين ساترين مسح عليهما يوم وليلة للمقيم وثلاثة أيام بلياليها للمسافر إذا كان هذا على طهارة إذا لبسهما على طهارة. نعم.","link":"https://binbaz.org.sa/fatwas/7432/احكام-المسح-على-الجوارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15407.mp3","categories":["المسح على الخفين"]},{"id":9610,"question":"يسأل أيضاً ويقول: كم عدد مرات المسح على الخفين هل هي ثلاث مرات مثل الوضوء أم مرةً واحدة؟","title":"عدد المسح على الخفين","answer":"الجواب: مثل الرأس مرةً واحدة، يمسح بيده اليمنى على خفه الأيمن وبيده اليسرى على خفه الأيسر مرةً واحدة كالرأس ولا حاجة إلى التكرار. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7784/عدد-المسح-على-الخفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_249/24910.mp3","categories":["المسح على الخفين"]},{"id":10092,"question":"تقول قرأت عن مشروعية المسح على الخفين، فما هو وصف الخف، وما هي صفة المسح وتوقيته؟ وهل ينطبق ذلك على الجورب حتى ولو كان رقيقًا؟","title":"معنى الخف وحكم المسح عليه وعلى الجورب","answer":"الجواب: الخف: ما يتخذ من الجلد للرجلين يستر الرجلين، يقال له: خف؛ يستر القدم والكعبين، هذا يقال له: خف، يمسح عليه المسلم ثلاثة أيام بلياليها إذا كان مسافرًا، ويومًا وليلة إذا كان مقيماً، والمرأة كذلك إن كانت مقيمة يوم وليلة، وإن كانت مسافرة ثلاثة أيام بلياليها، والجورب حكمه حكم الخف، إذا كان جورب من قطن أو صوف أو غيرهما ساتراً للقدمين فإنه يمسح عليه كالخف يوم وليلة للمقيم وثلاثة أيام للمسافر بشرط أن يكون ساترًا، أما إن كان شفافًا لا يستر فلا يمسح عليه، لابد أن يكون الجورب ساترًا كالخف للرجل للقدم والكعبين، والمسح يكون يوماً وليلة للمقيم يبدأ من المسح بعد الحدث، يبدأ اليوم والليلة من المسح بعد الحدث، وفي حق المسافر ثلاثة أيام بلياليها يبدأ من المسح بعد الحدث، أما لو لبسها لبس الخفين لبسهما الظهر وبقي على طهارته العصر والمغرب والعشاء ولم يحدث إلا بعد العشاء فإن المدة تبدأ من المسح بعد العشاء، إذا مسح في التهجد من الليل أو في آخر الليل يبدأ من المسح بعد الحدث وما مضى قبل ذلك لا يحسب. نعم.","link":"https://binbaz.org.sa/fatwas/8261/معنى-الخف-وحكم-المسح-عليه-وعلى-الجورب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27620.mp3","categories":["المسح على الخفين"]},{"id":10127,"question":"يقول: حدثونا بالتفصيل لو تكرمتم عن المسح على الجوارب، جزاكم الله خيراً؟","title":"حكم المسح على الجوارب وطريقته","answer":"الجواب: الصواب أنه لا حرج في المسح على الجوارب كالخفين من الجلد، قد مسح عليها النبي ﷺ في النعلين ومسح عليها جماعة من الصحابة فلا بأس بذلك، والجورب ما يلبس في الرجل من القطن أو الصوف أو الشعر أو غيرها غير الجلود إذا كان ساتراً للقدم يمسح عليه يوم وليلة للمقيم وثلاثة أيام بلياليها للمسافر بعد الحدث، يعني: يبتدي المسح بعد الحدث فيمسح يوم وليلة بعد الحدث في حق المقيم ويمسح ثلاثة أيام بلياليها بعد الحدث في حق المسافر، على الجورب وعلى الخف من الجلد كله واحد، هذا هو الصواب. نعم.\nالمقدم: إذا كان في الخف بعض المزوق سماحة الشيخ؟\nالشيخ: الشقوق اليسيرة يعفى عنها، الشقوق اليسيرة يعفى عنها في أصح قولي العلماء، الشقوق اليسير عرفاً يسمح عنها لأن الرسول ﷺ قال: يسروا ولا تعسروا، والله يقول سبحانه: وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ [الحج:78]، ولأن الناس قد لا تسلم خفافهم من الشقوق أو الفتوق، لكن إذا تحرز واعتنى بالخف وبالجورب حتى لا يكون فيه شيء يكون هذا أسلم لدينه وفيه خروج من خلاف العلماء القائلين بأنه لا يسمح بالخروق ولو يسيرة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8303/حكم-المسح-على-الجوارب-وطريقته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_305/30509.mp3","categories":["المسح على الخفين"]},{"id":10244,"question":"يسأل ويقول: هل يجوز المسح على جوارب النايلون أو لا يجوز جزاكم الله خيراً؟","title":"حكم المسح على جوارب النايلون","answer":"الجواب: يجوز المسح على الجوارب من أي جنس كانت، من صوف أو من وبر، من أي شيء إذا كان ساترة للرجلين للكعبين والقدمين، إذا كانت ساترة جاز المسح عليها من أي جنس، سواء كانت من الصوف أو من الوبر أو من القطن، أو من مادة أخرى تستر القدمين. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8414/حكم-المسح-على-جوارب-النايلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27902.mp3","categories":["المسح على الخفين"]},{"id":10675,"question":"ما الحكم إذا مسح المقيم أكثر من يوم وليلة ناسياً؟ هل يعيد صلاته أيضاً؟ أم ماذا يفعل؟","title":"حكم مسح المقيم على خفيه أكثر من يوم وليلة ناسياً","answer":"الجواب: هذا هو الصواب؛ لأن المدة محدودة ليوم وليلة، فإذا مضت المدة ونسي وصلى بالمسح فإنه يعيد ما زاده؛ لأنه صلاها في الحقيقة بغير وضوء فيعيد. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8857/حكم-مسح-المقيم-على-خفيه-اكثر-من-يوم-وليلة-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33007.mp3","categories":["المسح على الخفين"]},{"id":10875,"question":"بعد هذه الرسائل رسالة من إحدى الأخوات المستمعات من الرياض تقول: المرسلة (خ. أ. ع) أختنا لها عدد من الأسئلة -أربعة- تقول في أحدها: اختلف العلماء في حكم المسح على الجوارب الرقيقة، فما هو الصحيح؟ وما الدليل على عدم جواز المسح؟","title":"ما حكم المسح على الجوارب الرقيقة؟","answer":"الجواب:  الصواب أن المسح يكون على الساتر الصفيق الذي يستر القدمين؛ لأن الله أباح لنا المسح على الخفين رحمة لنا، فإذا كان الخفان غير ساترين لم يحصل المقصود، الأقدام بائنة ظاهرة، والظاهر حكمه الغسل، والنبي ﷺ مسح والصحابة على خفين ساترين. فالواجب التأسي بهم في ذلك؛ لأنهم مسحوا على أخفاف، وعلى جوارب ساترة، فلا يجوز أن يمسح على جوارب، أو أخفاف غير ساترة، لكن ذكر جمع من أهل العلم أن الخروق اليسيرة عرفًا لا تضر، تغتفر؛ لأنه قد لا يسلم الخف أو الجورب من شيء يسير يعتريه من فتق، أو خرق، أو نحو ذلك إذا كان يسيرًا عرفًا لا يستفحش، وإذا حرص وصارت الأخفاف سليمة، والجوارب سليمة كان ذلك أحوط، وفيه خروج من خلاف العلماء، والبعد عن الشبهة، وبكل حال فالشيء اليسير يعفى عنه، إن شاء الله. المقدم: الحمد لله جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9054/ما-حكم-المسح-على-الجوارب-الرقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_358/35808.mp3","categories":["المسح على الخفين"]},{"id":11054,"question":"هذا السائل يقول: كم مرة يحق للمسلم أن يمسح على خفيه أو جوربيه، فإذا كان مقيمًا، وتوضأ، ولبس الجورب السميك، ومضى عليه يوم، فهل يحق له التجديد، وكم مرة يحق له ذلك، جزاكم الله خيرًا؟","title":"مدة المسح على الخفين أو الجوربين","answer":"الجواب:  إذا لبس الخفين على طهارة يمسح عليها يومًا وليلة بعد الحدث إذا كان مقيمًا، أما إذا كان مسافرًا فإنه يمسح ثلاثة أيام بلياليها، هكذا وقت النبي ﷺ وما قبل الحدث لا يحسب، لو لبسها مثلًا الضحى، وبقي على طهارته الظهر والعصر والمغرب والعشاء؛ لا تُحسب، لكن يُحسب من حين أحدث بعد العشاء، تبدأ اليوم والليلة من حين أحدث، فالمسح بعد الحدث يكون: يومًا وليلة. فالمقصود: أنه تحسب عليه المدة بعد حدثه من مسحه بعد الحدث، نعم.","link":"https://binbaz.org.sa/fatwas/9232/مدة-المسح-على-الخفين-او-الجوربين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28810.mp3","categories":["المسح على الخفين"]},{"id":11055,"question":"في الفقرة الثانية يقول سماحة الشيخ: هل لذلك نية يتلفظ بها عند المسح؟","title":"حكم التلفظ بالنية عند مسح الخفين أو الجوربين","answer":"الجواب:  ليس لها نية، ما فيه نية، تكفي نية الوضوء والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9233/حكم-التلفظ-بالنية-عند-مسح-الخفين-او-الجوربين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28811.mp3","categories":["المسح على الخفين"]},{"id":11460,"question":"بعد هذا يسأل سماحتكم ويقول: إنني ألبس حذاءً -أجلكم الله- طويلًا يصل إلى الركبة، وهو مصنوع من البلاستك، هل يجوز أن أصلي به صلاة الفجر إذا أدخلت رجلي طاهرة؟ جزاكم الله خيرًا. الشيخ: رده.المقدم: يقول: إنني ألبس حذاءً بلاستك طويلُا، يصل إلى الركبة، فهل يجوز أن أصلي به صلاة الفجر إذا أدخلت رجلي طاهرة؟ جزاكم الله خيرًا.","title":"حكم الصلاة بنعل يغطي القدم والكعبين","answer":"الجواب:  نعم إذا لبسته على طهارة لك مدة يوم وليلة إذا كنت مقيمًًا، مدة يوم وليلة، وإن كنت مسافرًا ثلاثة أيام بلياليها، إذا كان هذا ساترًا للقدم مع الكعبين؛ فالحمد لله، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9641/حكم-الصلاة-بنعل-يغطي-القدم-والكعبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38115.mp3","categories":["المسح على الخفين"]},{"id":11548,"question":"ننتقل إلى رسالة أخرى ومواضيع أخر، الرسالة من المستمع (ع. ك. م) سوداني أيضًا ومقيم في شمال المملكة يسأل جمعًا من الأسئلة، من بينها سؤال عن حكم المسح على الشراب، أو المسح على الحذاء -أجلكم الله- وإذا كان يعلق بها بعض الأوساخ، فهل تجوز الصلاة بها؟","title":"حكم المسح على الجورب والخف","answer":"الجواب:  المسح على الخفين والجوربين هو الصح وسنة فعلها النبي ﷺ وفعلها أصحابه -رضي الله عنهم وأرضاهم- وقال -عليه الصلاة والسلام- في الحديث الصحيح: إذا توضأ أحدكم، فلبس خفيه؛ فليمسح عليهما وقال فيما رواه مسلم في الصحيح عن علي : يمسح المقيم يومًا وليلة، والمسافر ثلاثًا بلياليها. وهكذا روى صفوان بن عسال: أن النبي ﷺ: أمرهم إذا لبسوا الخفاف على طهارة أن يمسحوا يومًا وليلة للمقيم، وثلاثة أيام للمسافر بلياليها وهو ﷺ فعل ذلك: كان يمسح على الخفين .... بعض أسفاره ﷺ: توضأ ومعه المغيرة يصب عليه، فلما مسح رأسه، أراد المغيرة أن ينزع خفيه فقال: دعهما فإني أدخلتهما طاهرتين فمسح عليهما -عليه الصلاة والسلام-.  والجورب من جنس الخف، الجورب يكون من الصوف، أو من القطن، أو من الشعر، أو غير ذلك، هو من جنس الخف، الخف من الجلد، والجورب من غير الجلد، والصواب أنه يجوز المسح على الجورب ........ إذا ستر القدمين مع الكعبين ... يومًا وليلة للمقيم، وثلاثة أيام بلياليها للمسافر. وإذا كان الجورب في النعل ومسح عليهما جميعًا؛ فلا بأس، لكن إذا خلع النعل؛ يخلع الجورب، أما إذا مسح الجورب وحدها؛ فإنه يخلع النعل متى شاء، ويكون الحكم معلقًا بالجورب، يمسح يومًا وليلة في الإقامة، وثلاثة أيام بلياليها في السفر. أما النعل وحدها فلا يمسح عليها؛ لأنها لا تستر، وإنما يمسح على الجورب بالنعل، وقد ثبت عنه ﷺ أنه مسح على الجوربين والنعلين -عليه الصلاة والسلام- فإذا مسح عليهما جميعًا؛ صار الحكم لهما، يخلعهما جميعًا ويبقيهما جميعًا. أما إذا مسح على الجورب وحده؛ فإنه يكون الحكم للجورب والنعل متى شاء خلعها، ومتى شاء لبسها، فإذا مضى على الجورب في رجله يومًا وليلة بعد الحدث، وبعد المسح؛ خلعه. وهكذا الخف يبدأ من المسح بعد الحدث فإذا مضى يومًا وليلة، أربع وعشرين ساعة، يعني مضى أربع وعشرون ساعة بعد المسح، المسح الأول عليه بعد الحدث تمت المدة، وهكذا المسافر ثلاثة أيام بلياليها يعني: اثنتين وسبعين ساعة في حق المسافر، لكن لابد أن يكون على طهارة لبسهما على طهارة، ولابد أن يكون اللبس في الحدث الأصغر، أما في الجنابة لا، لا يمسح، وهكذا الحائض والنفساء لا تمسح، المسح في الحدث الأصغر، أما الجنب فيخلع، والحائض تخلع، والنفساء تخلع، لا يتصور في حق الحائض والنفساء؛ لأنها لا طهارة لهما إلا بعد الغسل. فالحاصل أن الجورب إنما يمسح عليه للوضوء أما في الجنب في الجنابة لا يخلع. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9731/حكم-المسح-على-الجورب-والخف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_296/29604.mp3","categories":["المسح على الخفين"]},{"id":11955,"question":"يرجو من سماحتكم أن تتفضلوا ببيان أحكام المسح على الشراريب، جزاكم الله خيرًا.","title":"حكم المسح على الجوربين وشروطه","answer":"الجواب:  المسح على الخفين والشراب مشروع، إذا كان الخف ساترًا والشراب ساترًا ولبسهما على طهارة، فالخف يكون من الجلد، والشراب والجورب يكون من الصوف، أو الوبر، أو القطن، أو نحو ذلك، فإذا كان الجورب ساترًا، والخف ساترًا، ولبسهما على طهارة؛ شرع له المسح يومًا وليلة بعد الحدث، وبعد المسح، في حال الإقامة، وثلاثة أيام بلياليها في حال السفر، فالمقيم يوم وليلة والمسافر ثلاثة أيام بلياليها بدءًا من المسح بعد الحدث، إذا كان لبسهما على طهارة، وكانا ساترين، الخفان، أو الجوربان، والخروق اليسيرة جدًا عرفًا يعفى عنها -إن شاء الله- نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10140/حكم-المسح-على-الجوربين-وشروطه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42819.mp3","categories":["المسح على الخفين"]},{"id":12013,"question":"يقول: كيف يكون المسح على الشراب عند الوضوء، هل يبدأ برجل، ويلبس الشراب، أو بعد الوضوء والتنشيف؟ وهل يجوز حسب الظروف فرضًا؟ أرجو أن توجهوني جزاكم الله خيرًا.","title":"المسح على الجوربين وشروطه","answer":"الجواب:  يمسح على الشراب مثلما يمسح على الخف الجلد، إذا كان عليه جوربان وقد لبسهما على طهارة؛ يمسح عليهما مثلما يمسح على الجوربين، يمسح على اليمنى باليمنى، ثم يمسح على اليسرى باليسرى، ويكفي ذلك، والحمد لله، على ظاهر القدم يمسح ظاهر الخفين، ظاهر الجوربين، ويكفي ذلك. أما عند البدء فلا يمسح عليهما إلا إذا كان لبسهما على طهارة، يلبسهما على طهارة، لابد أن يتوضأ أولًا، ثم يلبسهما، وإذا لبس الخف، أو الجورب في الرجل اليمنى قبل أن يكمل الوضوء، ثم غسل اليسرى ولبس؛ فالأحوط له أن يخلع اليمنى، ثم يلبسها بعد كمال الوضوء؛ لأنه لبسها قبل كمال الوضوء، فيخلعها بعدما غسل اليسرى، ثم يعيد لبسها، حتى يكون لبسها على طهارة كاملة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10198/المسح-على-الجوربين-وشروطه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43204.mp3","categories":["المسح على الخفين"]},{"id":12074,"question":"المستمع (سليمان . م) بعث يسأل ويقول: تعرضت إلى كسر في ساقي، ووضع عليه الجبس، وعند الوضوء أمسح على الجبس، فهل وضوئي صحيح؟","title":"حكم المسح على الجبس واشتراط الطهارة في ذلك","answer":"الجواب:  نعم. عليك أن تمسح على الجبس، كالجبيرة، مثل الجبيرة حتى يزال، إذا كان الجبس على القدم، أما إذا كان الساق؛ فلا تمسح عليه، إذا كان الجبس بعضه على القدمين، أو على أحد القدمين؛ تمسح عليه عند الوضوء مثل لو كانت جبيرة من خرقة، أو غيرها على القدم؛ تمسح عليها حتى تزال، نعم. المقدم: جزاكم الله خيرًا، لا يشترط كونه قد وضع الجبس وهو على طهارة سماحة الشيخ؟ الجواب: لا يشترط على الصحيح، الجبيرة الجبس لا يشترط فيه الطهارة، الطهارة في الخفين، لابد أن يلبسهما على طهارة، أما الجبيرة قد تقع له وهو على غير طهارة، يضطر إلى فعلها، وهو على غير طهارة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10259/حكم-المسح-على-الجبس-واشتراط-الطهارة-في-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_435/43507.mp3","categories":["المسح على الخفين"]},{"id":12542,"question":"من اليمن الشمالي رسالة وصلت إلى البرنامج من أحد الإخوة وقع في نهايتها، يقول: الأستاذ: صلاح طاهر أبو غنام، فلسطيني يعمل باليمن الشمالي، يقول في أحد أسئلته: كما نعرف بالنسبة للمسح على الخفين، فإنه يجوز المسح للمقيم يومًا وليلة، أي: بمعنى خمسة أوقات، والسؤال هو: متى يبدأ وقت المسح؟ هل يبدأ من لبس الخف؟ أم يبدأ من بداية المسح؟","title":"بداية وقت المسح على الخفين","answer":"الجواب:  الصواب أنه يبدأ من المسح بعد الحدث، إذا لبسته على طهارة، ثم أحدثت ببول، أو ريح، أو غيرهما، ثم توضأت أول وضوء هذا هو المبدأ، فإذا أحدثت مثلًا: بعد الظهر، ثم توضأت للعصر؛ يكون وضوء العصر هو أول شيء، فإذا جاء العصر الثاني تخلع. وهكذا لو أحدثت الضحى، ومسحت على الخفين بعد الطهارة من الظهر يكون المبدأ الظهر، فإذا جاء الظهر غدًا خلعت، وتوضأت للظهر، وهكذا، البدء يكون من المسح بعد الحدث في الطهارة التي بعد الحدث أول ما لبست. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10747/بداية-وقت-المسح-على-الخفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45610.mp3","categories":["المسح على الخفين"]},{"id":12748,"question":"هل يجوز المسح على الشراب في الوضوء؛ وذلك كالمسح على الخفين، جزاكم الله خيرًا؟","title":"حكم المسح على الجوارب","answer":"الجواب:  نعم، يمسح على الشراب من القطن، أو الصوف كما يمسح على الخفين من الجلد، وكان جماعة من الصحابة يمسحون على الجوارب، بل جاء عنه ﷺ في الحديث الصحيح: أنه مسح على الجوربين والنعلين -عليه الصلاة والسلام- فلا حرج في ذلك إذا لبسهما على طهارة، وكانا ساترين؛ يمسح عليهما يومًا وليلة للمقيم، وثلاثة أيام بلياليها للمسافر. ويبدأ المسح بعد الحدث، يومًا وليلة بعد الحدث، يومًا وليلة، أربعة وعشرين ساعة، والمسافر ثلاثة أيام بلياليها، يعني: اثنتين وسبعين ساعة، بعد الحدث. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10962/حكم-المسح-على-الجوارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41819.mp3","categories":["المسح على الخفين"]},{"id":13298,"question":"نعود إلى رسالة بعث بها سائل للبرنامج يقول في هذا السؤال مصري الجنسية، ويعمل بالمنطقة الشرقية، يقول: أشاهد أثناء الوضوء البعض من الناس يمسحون على الشراب، الجورب- أي: ما يلبس في القدم- فما حكم ذلك، وما هي ظروف وشروط المسح على الشراب؟","title":"المسح على الخفين ومدته","answer":"الجواب: لا مانع من المسح على الشراب؛ لأن الرسول ﷺ مسح على الجوربين، ومسح الصحابة -رضي الله عنهم وأرضاهم-والجوربان ما يتخذ للرجلين من صوف، أو قطن، أو غيرهما إذا كانا ساترين للقدم والكعب؛ فلا بأس، يمسح عليهما يومًا وليلة للمقيم بعد الحدث، وثلاثة أيام بلياليها للمسافر. هكذا جاءت السنة عن النبي ﷺ المقيم يمسح يومًا وليلة، تبدأ من مسحه بعد الحدث أول مسح من بعد الحدث، هذا المبدأ، وفي السفر ثلاثة أيام بلياليها، تبدأ من المسح بعد الحدث أول مسح؛ حتى يكمل مدة ثلاثة أيام، والجوربان مثل الخفين، الخف يكون من الجلد مثلًا، والجورب يكون من الصوف، والقطن، ونحو ذلك، فكما يمسح على الخف يمسح على الجورب إذا كان كل منهما ساترًا للقدم والكعبين، يومًا وليلة للمقيم إذا لبسهما على طهارة، وثلاثة أيام للمسافر بلياليها إذا لبسها على طهارة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11583/المسح-على-الخفين-ومدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52208.mp3","categories":["المسح على الخفين"]},{"id":13668,"question":"السائل إبراهيم أبو حامد له آخر سؤال في هذه الرسالة: ما حكم المسح على الشراب الخفيف الذي يبين لون البشرة؟","title":"حكم المسح على الشراب الذي يبين لون البشرة","answer":"الجواب: إذا كان الشراب لا يستر، لا يمسح عليه، لا يمسح إلا على جورب يستر، يستر القدم، أما الذي لا يستر؛ فلا يمسح عليه. نعم. المقدم: جزاكم الله خيرًا فضيلة الشيخ.","link":"https://binbaz.org.sa/fatwas/12012/حكم-المسح-على-الشراب-الذي-يبين-لون-البشرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52911.mp3","categories":["المسح على الخفين"]},{"id":14006,"question":"تسأل أختنا وتقول: ما هي كيفية المسح على الجورب؟ مثلًا: أتوضأ لصلاة الفجر، ثم ألبس الجورب وأمسح عليه عند الوضوء لصلاة الظهر في المدرسة حيث أني أعمل معلمة، وعند عودتي للمنزل، أخلعه وأتوضأ بعد ذلك الوضوء العادي، فهل هذا جائز؟","title":"حكم المسح على الجوربين لصلاة ثم خلعه","answer":"الجواب: لا بأس لا حرج في ذلك.\nالمقدم: الحمد لله.\nالشيخ: من لبس الخفين أو الجوربين إن شاء أبقاهما يومًا وليلة وهو مقيم غير مسافر، وإن شاء خلعهما متى شاء، ولو لم يصل فيهما إلا مرة واحدة، لكن له رخصة أن تبقى عليه أربعة وعشرين ساعة بعد المسح، بعد الحدث والمسح أربعة وعشرين ساعة يوم وليلة، والمسافر له ثلاثة أيام، يعني: اثنتين وسبعين ساعة ثلاثة أيام بلياليها، بعد الحدث والمسح، فالحاصل أنه لا بأس أن يمسح عليها وقتًا أو وقتين ثم يخلع، لا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12428/حكم-المسح-على-الجوربين-لصلاة-ثم-خلعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_606/60609.mp3","categories":["المسح على الخفين"]},{"id":14016,"question":"سماحة الشيخ! لاحظت أن بعض المسلمين يمسح على حذائه مثلًا وهو يرتدي الجورب، فإذا ما دخل المسجد خلع الحذاء وهو يعتقد أن المسح بتلك الصورة صحيح، هل هو صحيح فعلًا؟","title":"حكم صلاة من خلع الحذاء الممسوح عليه","answer":"الجواب: هذا ما يصح.\nالمقدم: لا يصح!\nالشيخ: لابد يكون المسح على الجورب، فإذا مسح على النعل مع الجورب، وخلع النعل؛ يخلع الجورب، انتهى الوضوء.. بطل الوضوء، فإذا مسح عليهما جميعًا يبطل الوضوء بخلع أحدهما، أما إذا خص المسح بالجورب، ثم لبس الكندرة أو النعل؛ فلا يضر ذلك إذا خلعها لا بأس، يكون الحكم للجورب، وإذا خلع النعل أو الكندرة التي على الجورب؛ لا يضر، أما إذا مسح عليهما جميعًا، فالحكم يتعلق بهما جميعًا، إذا خلع واحدًا خلع الآخر وبطل الوضوء.\nومما ينبغي التنبه له: أن المسح على ظاهر القدم فقط، ظاهر القدم لا يحتاج إلى العقب، ولا أسفل الخف، متى مسح على ظاهر قدميه كفى، كان النبي ﷺ يمسح على ظاهر الخفين فقط، على ظاهر القدم، فلا يجب مسح العقب ولا مسح الأسفل، إنما السنة مسح الظاهر فقط، مثلما قال علي : \"لو كان الدين بالرأي؛ لكان أسفل الخف أولى بالمسح من أعلاه، وقد رأيت النبي ﷺ يمسح على ظاهر خفيه\"، عليه الصلاة والسلام، فالحاصل: أن هذا هو محل المسح، ظاهر الخف وظاهر الجورب.\nوهنا مسألة أيضًا قد تخفى وهي مسألة الجبيرة، إذا كان الإنسان عليه جبيرة في قدمه أو في ذراعه أو في وجهه لجرح؛ فإنه يمسح عليها، وليس لها وقت معين، ما دامت موجودة يمسح، ولو طالت المدة حتى يشفى مما تحتها ويزيلها، وليس لهذا حد محدود إلا العافية، ويمسح عليها كلها على الجبيرة كلها، ولو كانت وضعت على غير طهارة، لو جرح مثلًا في يده أو في رجله وهو على غير وضوء، ثم وضع الجبيرة عليه، أو وضع الطبيب عليه الجبيرة؛ فإنه يمسح مطلقاً على الراجح، ولو كان وضعها حين وضعها على غير وضوء.\nوهكذا في الغسل غسل الجنابة، إذا كان في ظهره لزقة في ظهره أو في جنبه، أو جبيرة؛ فإنه يمر عليها الماء ويكفي عند الغسل، ولا حاجة إلى أن يزيلها، بل متى مرر عليها الماء كفى، حتى يعافيه الله. نعم.\nالمقدم: بارك الله فيكم، ذكرتم أنه لو كانت الجبيرة على حدث أصغر، ماذا عن الحدث الأكبر شيخ عبد العزيز ؟\nالشيخ: مثلما تقدم، ولو حدثًا أكبر.\nالمقدم: ولو حدث أكبر فالحكم واحد؟\nالشيخ: أبد، يمسح عليها في الوضوء، ويمر عليها الماء في الغسل.\nالمقدم: جزاكم الله خيرا.\nالشيخ: الحمد لله!\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12431/حكم-صلاة-من-خلع-الحذاء-الممسوح-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_606/60611.mp3","categories":["المسح على الخفين"]},{"id":14017,"question":"لعله من المناسب سماحة الشيخ أن تتفضلوا بذكر الشروط التي يجب على المسلم مراعاتها إذا ما أراد المسح على الخفين أو الجوربين.","title":"شروط المسح على الخفين أو الجوربين","answer":"الجواب: نعم، أولًا: لا بد من طهارة، أن يلبسهما على طهارة، كما قال النبي ﷺ لما أراد المغيرة أن ينزع خفيه قال: دعهما فإني أدخلتهما طاهرتين، فإذا أراد أن يمسح، فليلبسهما على طهارة، رجلاً كان أو امرأة، مسافرًا أو مقيمًا.\nثانيًا: لا بد من أن يكونا ساترين، الخفين أو الجوربين لا بد أن يكونا ساترين صفيقين، ويسمح بالخروق اليسيرة على الصحيح، إذا كانت خروق يسيرة عرفًا يعفى عنها على الصحيح.\nوالثالث: أن يكون المسح في المدة المعينة، يوم وليلة للمقيم، وثلاثة أيام بلياليها للمسافر، لا يمسح في أكثر من ذلك.\nفإذا توافرت هذه الشروط؛ فالمؤمن يمسح على الخفين والجوربين، والمرأة كذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12430/شروط-المسح-على-الخفين-او-الجوربين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_606/60610.mp3","categories":["المسح على الخفين"]},{"id":14298,"question":"في ثاني أسئلته يقول: متى يبدأ المسح على الخفين؛ أهو من حين اللبس؟ أم من حين الحدث؟ أم من حين أول مسح بعد الحدث؟ فأيهما الراجح يا سماحة الشيخ؟ وما دليل ذلك مأجورين؟","title":"وقت بدء المسح على الخفين","answer":"الجواب: هذا هو الراجح؛ أن يكون من المسح بعد الحدث؛ لقوله ﷺ: يمسح المسافر ثلاثة أيام بلياليهن والمقيم يومًا وليلة فالبدء يكون من مسحه بعد الحدث، أما قبل الحدث طهارته ما هي بلازمة، لكن إذا أحدث ثم تطهر هذا أول شيء حتى يكمل ثلاثة أيام بلياليهن إن كان مسافرًا أو يوم وليلة -أربعة وعشرين ساعة- إن كان مقيمًا.","link":"https://binbaz.org.sa/fatwas/12763/وقت-بدء-المسح-على-الخفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54926.mp3","categories":["المسح على الخفين"]},{"id":14981,"question":"المرسلة أم عبدالله السالم العبدالمجيد، بعثت بهذه الرسالة تقول: إنني امرأة كفيفة وكبيرة، ومن الصعب علي خلع الكنادر، ثم المسح على الشراب، ثم لبس الكنادر، فهل يجوز أن أمسح على الكنادر فقط، وحينما أصلي أو أصل إلى السجادة أخلع الكنادر وأصلي؟","title":"حكم المسح على الكنادر وخلعها عند الصلاة","answer":"الجواب: المسح على ما يستر الرجلين من كنادر أو شراب جائز، رخصة من الله -جل وعلا-، وفيه تخفيف على الأمة، كان النبي ﷺ يمسح على خفيه وعلى جوربيه، ويصلي يوم وليلة في الحضر في الإقامة، وفي السفر ثلاثة أيام بلياليها، هذا مشروع، والحمد لله، لكن يكون المسح على الشيء الساتر: إما جورب ساتر، أو خف من الجلد ساتر يمسح عليه يوم وليلة في الإقامة بعد الحدث والمسح يوم وليلة. أما الكندرة فلا يمسح عليها، إذا كانت غير ساترة لا يمسح عليها، إلا إذا مسح عليها مع جورب لا بأس، يمسح عليهما جميعًا على الكندرة، وعلى ما ظهر من الجورب يمسح عليهما جميعًا لا بأس، وإن مسح عليهما جميعًا لا يخلع، فإذا خلع بطل الوضوء، بل يصلي في الجزمة والشراب جميعًا، فإذا خلع الجميع أو خلع الكندرة بطل الوضوء، وإذا أرادت هذه المرأة السلامة تمسح على الجورب فقط، وتخلي الجورب في شبشب أو غيره يخف عليها خلعه، أو في كندرة خفيفة يخف خلعها، تمسح على الجورب، وإذا جاءت المصلى خلعت الكندرة وكفاها الجورب، ولا تمسح على الكندرة، تمسح على الجورب الذي يستر القدم، والحمد لله.  وأما الكندرة لا تمسح عليها حتى تخلعها متى شاءت، أو تجعل الجورب في شبشب يقيها الأرض، ثم تخلع الشبشب. فالمقصود: أنها إذا مسحت على الكندرة ما يجزي؛ لأن الكندرة لا تستر إذا كانت قصيرة، أما إذا كانت الكندرة واسعة تستر القدم كله، مع الكعبين تمسح على الكندرة، ومتى مسحت عليها فلا تخلعها إلا بعد الصلاة، تصلي أول، فإن خلعتها قبل الصلاة بطل الوضوء، فينبغي التنبه لهذا، ينبغي التنبه من المرأة، والذي يقرأ عليها يسمعها هذا الجواب، يفهمها أن المسح على الكندرة لا يجزئ إذا كانت قاصرة ما تستر الكعبين، وإذا خلعتها بطل وضوؤها، فالذي ينبغي لها أن تمسح الجورب وتكتفي به، والكندرة تخلعها متى شاءت، نعم.\nالمقدم: إذًا الذي فهمنا -يا فضيلة الشيخ- أنه إذا كان على المسلم شراب وكندرة ومسح على الشراب والكندرة أنه لا يخلع الكندرة. الشيخ: إلا متى أراد إبطال الوضوء، وأما إذا أراد أنه يصلي فيهما فيبقيهما حتى يصلي، نعم.","link":"https://binbaz.org.sa/fatwas/13489/حكم-المسح-على-الكنادر-وخلعها-عند-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_651/nour_65106.mp3","categories":["المسح على الخفين","قضايا المرأة"]},{"id":14989,"question":"المرسلة أم عبدالله السالم العبدالمجيد، بعثت بهذه الرسالة تقول: إنني امرأة كفيفة وكبيرة، ومن الصعب علي خلع الكنادر، ثم المسح على الشراب، ثم لبس الكنادر، فهل يجوز أن أمسح على الكنادر فقط، وحينما أصلي أو أصل إلى السجادة أخلع الكنادر وأصلي؟","title":"حكم المسح على الكنادر وخلعها عند الصلاة","answer":"الجواب: المسح على ما يستر الرجلين من كنادر أو شراب جائز، رخصة من الله -جل وعلا-، وفيه تخفيف على الأمة، كان النبي ﷺ يمسح على خفيه وعلى جوربيه، ويصلي يوم وليلة في الحضر في الإقامة، وفي السفر ثلاثة أيام بلياليها، هذا مشروع، والحمد لله، لكن يكون المسح على الشيء الساتر: إما جورب ساتر، أو خف من الجلد ساتر يمسح عليه يوم وليلة في الإقامة بعد الحدث والمسح يوم وليلة. أما الكندرة فلا يمسح عليها، إذا كانت غير ساترة لا يمسح عليها، إلا إذا مسح عليها مع جورب لا بأس، يمسح عليهما جميعًا على الكندرة، وعلى ما ظهر من الجورب يمسح عليهما جميعًا لا بأس، وإن مسح عليهما جميعًا لا يخلع، فإذا خلع بطل الوضوء، بل يصلي في الجزمة والشراب جميعًا، فإذا خلع الجميع أو خلع الكندرة بطل الوضوء، وإذا أرادت هذه المرأة السلامة تمسح على الجورب فقط، وتخلي الجورب في شبشب أو غيره يخف عليها خلعه، أو في كندرة خفيفة يخف خلعها، تمسح على الجورب، وإذا جاءت المصلى خلعت الكندرة وكفاها الجورب، ولا تمسح على الكندرة، تمسح على الجورب الذي يستر القدم، والحمد لله.  وأما الكندرة لا تمسح عليها حتى تخلعها متى شاءت، أو تجعل الجورب في شبشب يقيها الأرض، ثم تخلع الشبشب. فالمقصود: أنها إذا مسحت على الكندرة ما يجزي؛ لأن الكندرة لا تستر إذا كانت قصيرة، أما إذا كانت الكندرة واسعة تستر القدم كله، مع الكعبين تمسح على الكندرة، ومتى مسحت عليها فلا تخلعها إلا بعد الصلاة، تصلي أول، فإن خلعتها قبل الصلاة بطل الوضوء، فينبغي التنبه لهذا، ينبغي التنبه من المرأة، والذي يقرأ عليها يسمعها هذا الجواب، يفهمها أن المسح على الكندرة لا يجزئ إذا كانت قاصرة ما تستر الكعبين، وإذا خلعتها بطل وضوؤها، فالذي ينبغي لها أن تمسح الجورب وتكتفي به، والكندرة تخلعها متى شاءت، نعم.\nالمقدم: إذًا الذي فهمنا -يا فضيلة الشيخ- أنه إذا كان على المسلم شراب وكندرة ومسح على الشراب والكندرة أنه لا يخلع الكندرة. الشيخ: إلا متى أراد إبطال الوضوء، وأما إذا أراد أنه يصلي فيهما فيبقيهما حتى يصلي، نعم.","link":"https://binbaz.org.sa/fatwas/13489/حكم-المسح-على-الكنادر-وخلعها-عند-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_651/nour_65106.mp3","categories":["المسح على الخفين","قضايا المرأة"]},{"id":15550,"question":"تقول السائلة: المسح على الجوارب، حكمه هل يصح أكثر من ثلاث مرات أتوضأ وأمسح، فهل يصح مثلًا ذلك العصر والمغرب والعشاء؟","title":"مدة المسح على الجوربين للمقيم","answer":"الجواب: يوم وليلة، من لبس الجوارب على طهارة يمسح يوم وليلة كالخفاف، فإذا لبس الجوربين الساترين بعد الطهارة مسح عليها يوم وليلة الرجل والمرأة، فإذا أتم اليوم والليلة خلعهما وتوضأ، كما يلبس الخفين، والجوارب تكون من القطن أو من الصوف إذا كانت ساترة، نعم. المقدم: حفظكم الله يا سماحة الشيخ، وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14086/مدة-المسح-على-الجوربين-للمقيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69122.mp3","categories":["المسح على الخفين"]},{"id":15603,"question":"هل يشترط سمك معين للمسح على الجوربين؟","title":"شرط الجورب الذي يصح المسح عليه","answer":"الجواب: ليس لهذا شرط، وليس لهذا حد محدود، ولكن المطلوب الستر، إذا سترت القدم لا يرى لون القدم، هل هو أبيض أو أحمر أو أسود، إذا كان الجورب ساترًا للقدم كفى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14141/شرط-الجورب-الذي-يصح-المسح-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70504.mp3","categories":["المسح على الخفين"]},{"id":15604,"question":"هل تشترط الطهارة عند المسح على العمامة، أو الربطة بالنسبة للمرأة؟ وكيفية المسح عليها؟جزاكم الله خيرًا.","title":"حكم الطهارة عند المسح على العمامة وغيرها","answer":"الجواب: العمامة كالخفين لا بد من الطهارة، إذا لبس العمامة المحنكة على طهارة مسح عليها يوم وليلة، وهكذا المرأة إذا أدارت الخمار على رأسها، وشق عليها نزعه؛ تمسح يوم وليلة إذا كان على طهارة، كالخفين سواء، أما إذا كان لا يشق كالعمامة العادية الغترة، فهذه ما عليها مسح؛ لأن خلعها لا يشق لا يكلف، كذلك الخمار العادي، أما إذا كان العمامة تحنك على الرأس، وتربط على الرأس، يكون في حلها بعض المشقة، فيمسح عليها يوم وليلة إذا لبسها على طهارة، وهكذا إذا كانت تدير الخمار على رأسها، وتربطه على رأسها، تمسح عليه يوم وليلة، إذا كان لبسها على طهارة، يعني: لبس الخمار على طهارة، نعم.\nالمقدم: ماذا عن الربطة لو تكرمتم سماحة الشيخ بالنسبة للمرأة؟\nالشيخ: ما أعرف الربطة ما هي الربطة؟ المقدم: مثل التحزيبة تمامًا، وقد سئلتم عنها فأجبتم. الشيخ: ما هي الربطة؟\nالمقدم: التحزيبة، أو الربطة، لفافة تربطها المرأة على رأسها حتى لا يرى من شعرها شيء، وأكثر ما يستخدم هذا لدى الطبيبات المسلمات، والممرضات المسلمات. الشيخ: إذا كانت تديرها على رأسها، تحنكها على رأسها، تديره على رأسها، تربطه على رأسها هي من جنس العمامة، من جنس الخمار.\nالمقدم: الحكم واحد.\nالشيخ: إذا كان على طهارة، نعم.\nالمقدم: جزاكم الله خيرًا، إذًا لها أن تمسح عليها إذا لبستها على طهارة؟ الشيخ: يوم وليلة، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14144/حكم-الطهارة-عند-المسح-على-العمامة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70505.mp3","categories":["المسح على الخفين"]},{"id":15993,"question":"يقول: مسحت على الخفين والشراريب معًا، ولكن نزعت الخفين خارج المسجد، وصليت بالشراريب فقط، هل صلاتي صحيحة؟","title":"حكم المسح على الخفين والشراب ثم الصلاة في الشراب","answer":"الجواب: إذا كنت مسحت عليهما جميعًا على الخف وعلى ما ظهر من الشراب، فاخلعهما جميعًا، أما إذا كنت مسحت على الشراب فقط.......، والشراب ساتر ومسحت عليه، فإنه يكفي، والحمد لله، ولو خلعت الخف، نعم. المقدم: يقول: مسحت عليهما جميعًا؟\nالشيخ: يخلعهما جميعًا إذا مسح عليهما جميعًا يخلعهما جميعًا، نعم.\nالمقدم: جزاكم الله خيرًا.\nالشيخ: أما إذا مسح على الجوربين أخرج رجليه ومسح على الجوربين، ثم أدخلهما في الكندرة، أو في الخف، فالأمر على الجوربين، إذا خلع الخف لا بأس، لا يضر. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14607/حكم-المسح-على-الخفين-والشراب-ثم-الصلاة-في-الشراب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74704.mp3","categories":["المسح على الخفين"]},{"id":16301,"question":"تقول: ما حكم المسح على الجوارب الرقيقة؛ وذلك للصلاة عندما أكون في المدرسة؛ ذلك لأن وقت الصلاة محدد بعشر دقائق، ومنها وقت الوضوء، فأمسح على الجوارب، وإن كانت خفيفة من أجل استغلال الوقت، فبم توجهونني؟ جزاكم الله خيرًا.","title":"حكم المسح على الجوارب الرقيقة","answer":"الجواب: الوقت هذا قصير، العشر الدقائق قصيرة، فننصح القائمة على المدرسة بأن تزيد المدة إلى نصف الساعة، أو نصفًا إلا خمسًا، لعل المرأة يعني الطالبة تستطيع أن تقضي حاجتها، وتتوضأ بسهولة، وتصلي بطمأنينة؛ لأن العشر الدقائق قليلة جدًا، وليس كل طالبة على وضوء، فقد تحتاج إلى وضوء، وإلى قضاء حاجة، وعليك ألا تمسحي على الجوارب الرقيقة، لابد أن تكون ساترة، وإلا فاخلعيها، واغسلي الرجل، لابد تكون ساترة صفيقة، تستر الرجل، لا تعرف الرجل هل هي حمراء، أو سوداء من دونها، بل تسترها سترًا كاملًا، وتستر الكعبين أيضًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14992/حكم-المسح-على-الجوارب-الرقيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753007.mp3","categories":["المسح على الخفين","قضايا المرأة"]},{"id":16515,"question":"من الدمام رسالة بعث بها المستمع (ف. ح. ش) ضمنها بعض الأسئلة في أحدها يقول: هل يشترط في المسح على الجورب النية؟ أي: أنني إذا لبسته على طهارة، وحان وقت الظهر، ولم أنو أن أمسح عليه، فهل تصح الصلاة، وإن مسحت عليه، أم لابد من وجود النية قبل المسح؟","title":"حكم النية للبس الجوربين والمسح عليهما","answer":"الجواب: لا حاجة إلى ذلك، لا يشترط النية، إذا لبسته على طهارة؛ جاز لك المسح عليه، وإن كنت لم تنو عند اللبس بأنك تمسح عليه، المهم أن تكون لبسته على طهارة، فلك المسح عليه حتى تمضي المدة، وهي يوم وليلة للمقيم، وثلاثة أيام بلياليها للمسافر بعد الحدث، يعني بعد... من أول مسح بعد الحدث، وليس هناك... ولا يشترط في هذا أن تسبق النية أنك تريد أن تمسح عليه، لا يشترط، ولا دليل على ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15227/حكم-النية-للبس-الجوربين-والمسح-عليهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75611.mp3","categories":["المسح على الخفين"]},{"id":16804,"question":"هل هناك شروط للمسح على الخفين، كأن يكون الخف سميكًا، أو أي شروط أخرى؟ جزاكم الله خيرًا.","title":"ما شروط المسح على الخفين؟","answer":"الجواب: نعم، لا بد من شروط: الأول: أن يكون على طهارة، تلبسه على طهارة، لابد. والثاني: أن يكون ساترًا ... من الكعبين إلى أطراف الأصابع، ساترًا لها. ثالثًا: أن يكون طاهرًا. الرابع: أن يكون مباحًا، ما هو بمغصوب، لابد أن يكون شيئًا مباحًا. فالحاصل: أنه إذا كان ساترًا، طاهرًا، مباحًا في يومه، وليلته؛ فلا بأس، تمسح عليه، أما إن كان ملبوسًا على غير طهارة، لا، تخلعه، أو كان نجسًا؛ تخلعه، أو كان مغصوبًا؛ تخلعه، وتعطيه أهله، أو كان رقيقًا لا يستر، أو مخرقًا خروقًا كثيرة، فهذا لا تمسح عليه، أما إذا كان خرقًا يسيرًا، خروقًا يسيرة صغيرة؛ فالصحيح أنه يغتفر -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15568/ما-شروط-المسح-على-الخفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82307.mp3","categories":["المسح على الخفين"]},{"id":17336,"question":"........... له عدة قضايا يثيرها سماحة الشيخ. الأولى: هي المسح على الجوارب بالنسبة لحالته، ما حكمه؟","title":"حكم المسح على الجوارب وإمامة صاحب الحدث الدائم","answer":"الجواب: لا بأس مثل غيره، يمسح على الجوارب والخفين، يمسح عليهما يومًا وليلة مثل غيره، وهكذا بالنسبة للإمامة لا يؤم الناس، الإمامة لا يؤم، يؤم غيره؛ لأن حدثه دائم، وقد ذهب جمع من أهل العلم إلى أنه لا يؤم، فينبغي لك أن لا تؤم يا أخي، يؤم غيرك. نعم. المقدم: جزاكم الله خيرًا، وإن كان أعلم الموجودين؟ الشيخ: لكن لو أم صحت صلاته، لو أم صحت صلاته؛ لأن طهارته مجزئة في حقه، طهارته مجزئة في حقه؛ لكن كونه يدع الصلاة لغيره أحوط، خروجًا من خلاف العلماء. نعم. المقدم: جزاكم الله خيرًا، يثير مسألة الأفضلية بالنسبة للإمام، والمأمومين سماحة الشيخ، إذا كان هو أفضل الموجودين كما يقول؟ الشيخ: نعم نعم. يؤم غيره ممن هو دونه، السالم من هذا الحدث. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16167/حكم-المسح-على-الجوارب-وامامة-صاحب-الحدث-الداىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_724/nour_72409.mp3","categories":["صلاة الجماعة","المسح على الخفين"]},{"id":17407,"question":"بالنسبة للمسح سماحة الشيخ هل يكفي أن يكون المسح مرة واحدة، أو أكثر من مرة على الجوربين؟","title":"عدد المسحات على الجوربين","answer":"الجواب: إذا مسح مرة؛ كفى، إذا مسح الجورب، أو مسح الرأس مرة؛ كفى، يكفي مرة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16271/عدد-المسحات-على-الجوربين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77110.mp3","categories":["المسح على الخفين"]},{"id":18319,"question":"هذا السائل يقول يا سماحة الشيخ! حدثونا حفظكم الله عن المسح عن الخفين متى يبدأ ومتى ينتهي؟","title":"مدة المسح على الخفين","answer":"الجواب: المسح على الخفين سنة والجوربين كذلك، إذا لبسهما على طهارة يبدأ من الحدث بعد المسح، إذا أحدث يمسح عليهما يوم وليلة للمقيم وثلاثة أيام ولياليها للمسافر، إذا كان الجورب ساترًا، والخف ساترًا يلبسهما على طهارة ويمسح على الخفين والجوربين يوم وليلة إن كان مقيمًا، بدءًا من الحدث إذا أحدث بعد اللبس ....... حدث بريح أو بول أو غائط هذا المبدأ، يبدأ بعده يوم وليلة إذا كان مقيمًا، أما المسافر له ثلاثة أيام بلياليها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17372/مدة-المسح-على-الخفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91310.mp3","categories":["المسح على الخفين"]},{"id":18321,"question":"تقول السائلة: (ن. م. الشهراني ): عندما أتوضأ في المدرسة لتأدية صلاة الظهر أمسح على الحذاء؛ وذلك لصعوبة خلع الحذاء، ولبسه مرة أخرى؛ ولبعد المسجد عن دورة المياه، فإذا وصلت إلى المسجد خلعت الحذاء وصليت فما حكم ذلك؟","title":"حكم صلاة من يمسح على الحذاء ثم يخلعها","answer":"الجواب: لا ما يجوز هذا، هذا يكون باطل الوضوء، لابد من لبس خف يستر القدمين، أو جورب يستر القدمين ويمسح عليه ويبقى حتى يصلي، يبقى عليه الخف أو الجورب حتى يصلي. أما يمسح على ظاهر الحذاء ثم يخلعه عند المسجد هذا يبطل ما تصح الصلاة، لابد من بقائه حتى يصلي فيه إذا كان ساترًا للقدمين، حذاء ساتر للقدمين كخف أو جورب من الصوف أو القطن يستر القدم، ويلبسه على طهارة ويمسح عليه ثم يصلي فيه ولا يخلعه قبل الصلاة. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/17374/حكم-صلاة-من-يمسح-على-الحذاء-ثم-يخلعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91311.mp3","categories":["المسح على الخفين"]},{"id":18505,"question":"في آخر أسئلة هذا السائل يقول: هل يصح مسح الأرجل أثناء الوضوء من خلف الجوارب؟","title":"كيفية المسح على الجوارب أثناء الوضوء","answer":"الجواب: تمسح من فوق، السنة مسحها من فوق، النبي ﷺ كان يمسح على خفيه على ظاهرهما فقط، أما مسح العقب وأسفل الخف هذا ليس بصحيح، خبر ضعيف. الصواب: أنه ﷺ كان يمسح على ظاهر خفيه كما رواه أبو داود بإسناد جيد عن علي  قال: كان النبي يمسح على ظاهر خفيه عليه الصلاة والسلام. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17599/كيفية-المسح-على-الجوارب-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78606.mp3","categories":["المسح على الخفين"]},{"id":18726,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: من الفائزية في بريدة، المهموم، كما وصف نفسه (م. ب. ص. س. ض) أخونا له مجموعة من الأسئلة، يسأل ويقول -وربما تكون السائلة امرأة شيخ عبد العزيز -: إنسان يمسح على شراب خفيف ترى من خلاله البشرة هل هذا جائز أو لا؟","title":"حكم المسح على الجورب الخفيف","answer":"الجواب: لا بد في الشراب والخفاف أن تستر القدم من الكعب إلى أطراف الأصابع، فإذا كان الشراب خفيفًا شفافًا يرى منه ما تحته من اللحم، ترى حمرته وسواده ونحو ذلك؛ فإنه لا يمسح عليه، بل يجب خلعه وغسل الرجل، وإنما يمسح على الشراب والخف الساتر، لكن لو وقع فيه خروق يسيرة عرفًا، فإنه يعفى عنها في أصح قولي العلماء، الخرق اليسير الذي كالمخيط وطرف الإصبع ونحو ذلك؛ فهذا يعفى عنه على الصحيح. وينبغي للمؤمن وللمؤمنة تفقد الخفاف والشراب حتى تكون ساترة، والخروق ينبغي أن ترفى أو ترقع أو يبدل بشيء ساتر خروجًا من خلاف العلماء واحتياطًا للدين، فإن الصلاة عمود الإسلام؛ فتجب الحيطة لذلك، أما إذا اتسع الخرق، فإنه يخلع وتغسل الرجل، وهكذا إذا كان شفافًا، فإنه يخلع وتغسل الرجل، نعم.","link":"https://binbaz.org.sa/fatwas/17849/حكم-المسح-على-الجورب-الخفيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_874/nour_87403.mp3","categories":["المسح على الخفين"]},{"id":19233,"question":"يسأل سماحتكم فيقول: ما كيفية المسح على الجوارب؟","title":"ما كيفية المسح على الجوارب؟","answer":"الجواب: المسح على الجوارب مثل الخفين، الخفان من الجلد والجوارب من القطن ونحوه، فيمسح على ظاهرهما، يضع اليمنى على قدم اليمنى، ويده اليسرى على قدمه اليسرى يمسح عليها، إذا مسح رأسه وأذنيه فإنه يمسح الجوربين والخفين، يضع يده اليمنى كفه اليمنى على ظاهر قدمه، ويمسح على قدمه اليمنى ويضع يده اليسرى على قدمه اليسرى ويمسح ويكفي. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18421/ما-كيفية-المسح-على-الجوارب ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73805.mp3","categories":["المسح على الخفين"]},{"id":19459,"question":"رسالة وصلت إلى البرنامج من الجماهيرية الليبية وباعثها مستمع رمز إلى اسمه بالحروف (د) و (ق)، أخونا له عدد من الأسئلة في أحدها يقول: في فصل الشتاء تبرد قدماي، وتصبح في برود الثلج، وتتورم ويسبب لي ألمًا شديدًا خاصة في الليل؛ فأذهب إلى الطبيب ونصحني بلبس الجوارب عليها حتى تصبح دافئة، ولذلك أضطر إلى لبس أكثر من جورب في وقت واحد، وسؤالي عن المسح كيف يكون؟ جزاكم الله خيرًا.","title":"كيفية المسح على الجوربين","answer":"الجواب: تلبس الجورب أو الجوربين عليها للدفء وتمسح عليها؛ إذا لبستها على طهارة كل يوم وليلة، إذا مضى اليوم والليلة، تخلع ثم تتوضأ ثم تلبسها مرة أخرى وهكذا، كلما مر عليك يوم وليلة تخلع، تحسب بعد الحدث يوم وليلة، يعني: خمس صلوات في الغالب ثم تخلعها ثم تتطهر تغسلها، ثم تلبسها تلبس الجوارب وهكذا. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18705/كيفية-المسح-على-الجوربين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74020.mp3","categories":["المسح على الخفين"]}]
